[data-gesicomm-base="producto"] .gallery-main img[data-gesicomm-imagen-principal],
[data-gesicomm-base="producto"] [data-gesicomm-imagen-principal] {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
